-- HG shared platform migration (schema: lms)
-- Source: lms-hg/supabase/migrations/20260928092900_phase3_curriculum_hierarchy.sql
-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- Phase 3: lock the Track -> Module -> Session hierarchy (forward-only).
--   modules.parent_id IS NULL      -> Track
--   modules.parent_id = <track id> -> Module (leaf; teachable; has sessions)
-- Teaching grants stay exact-Module (no inheritance); "select all in Track" is
-- a UI bulk operation that writes one row per Module.
BEGIN;

-- 1. Track-level teaching grants confer nothing under the exact-Module model
--    (a session can never target a Track), so remove any that exist.
DO $cleanup$
DECLARE
  removed integer;
BEGIN
  DELETE FROM lms.module_teaching_permissions g USING lms.modules m
  WHERE m.id = g.module_id AND m.parent_id IS NULL;
  GET DIAGNOSTICS removed = ROW_COUNT;
  IF removed > 0 THEN
    RAISE NOTICE 'Removed % Track-level teaching grant(s); grant individual Modules instead', removed;
  END IF;
END;
$cleanup$;

-- 2. Teaching grants: only for an existing, non-deleted Module inside a Track.
CREATE FUNCTION lms.validate_teaching_grant_module() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  PERFORM 1 FROM lms.modules
  WHERE id = NEW.module_id AND parent_id IS NOT NULL AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'Teaching permissions can only be granted for a Module within a Track';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION lms.validate_teaching_grant_module() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER validate_teaching_grant_module BEFORE INSERT OR UPDATE OF module_id
  ON lms.module_teaching_permissions FOR EACH ROW EXECUTE FUNCTION lms.validate_teaching_grant_module();

-- 3. New sessions always target a Module, never a Track.
CREATE FUNCTION lms.validate_session_module() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  PERFORM 1 FROM lms.modules WHERE id = NEW.module_id AND parent_id IS NOT NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Sessions must belong to a Module, not a Track';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION lms.validate_session_module() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER validate_session_module BEFORE INSERT ON lms.curriculum_sessions
  FOR EACH ROW EXECUTE FUNCTION lms.validate_session_module();

-- 4. Keep the hierarchy two levels deep and stop a teachable Module with
--    grants or sessions from silently becoming a Track (or vice versa).
CREATE FUNCTION lms.guard_module_hierarchy() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NEW.parent_id IS NOT NULL THEN
    IF NEW.parent_id = NEW.id OR NOT EXISTS (
        SELECT 1 FROM lms.modules WHERE id = NEW.parent_id AND parent_id IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A Module''s parent must be a Track';
    END IF;
    IF TG_OP = 'UPDATE' AND EXISTS (SELECT 1 FROM lms.modules WHERE parent_id = NEW.id) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A Track with Modules cannot be moved into another Track';
    END IF;
  ELSIF TG_OP = 'UPDATE' AND OLD.parent_id IS NOT NULL AND (
      EXISTS (SELECT 1 FROM lms.module_teaching_permissions WHERE module_id = NEW.id)
      OR EXISTS (SELECT 1 FROM lms.curriculum_sessions WHERE module_id = NEW.id)) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'A Module with teaching permissions or sessions cannot become a Track';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION lms.guard_module_hierarchy() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER guard_module_hierarchy BEFORE INSERT OR UPDATE OF parent_id ON lms.modules
  FOR EACH ROW EXECUTE FUNCTION lms.guard_module_hierarchy();

-- 5. Session RPCs reject Tracks with a clear message before any write.
CREATE OR REPLACE FUNCTION lms.list_session_teacher_candidates(target_module_id uuid)
RETURNS TABLE (candidate_id uuid, candidate_name text, candidate_is_super_admin boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NOT (lms.has_admin_permission('manage_sessions') AND lms.can_teach_module(target_module_id)) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Session management permission required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM lms.modules WHERE id = target_module_id AND parent_id IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Sessions must belong to a Module, not a Track';
  END IF;
  RETURN QUERY
  SELECT u.id, u.full_name, u.role = 'super_admin' FROM lms.users u
  WHERE u.is_active AND u.deleted_at IS NULL
    AND (u.role = 'super_admin' OR (u.role = 'admin' AND EXISTS (
      SELECT 1 FROM lms.module_teaching_permissions g
      WHERE g.user_id = u.id AND g.module_id = target_module_id)))
  ORDER BY u.full_name NULLS LAST, u.id;
END;
$$;

-- 6. Learner provenance for every completed Module in one call. Historical:
--    derived from learner_progress.source_session_id -> sessions -> session
--    teachers, never from current grants or teacher_assignments.
CREATE FUNCTION lms.get_my_completions() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT CASE WHEN NOT lms.is_active_app_user(auth.uid()) THEN '[]'::jsonb ELSE coalesce((
    SELECT jsonb_agg(jsonb_build_object(
      'module_id', p.module_id, 'completed_at', p.completed_at, 'completion_method', p.completion_method,
      'session', CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object(
        'id', s.id, 'title', s.title, 'starts_at', s.starts_at) END,
      'teachers', (SELECT coalesce(jsonb_agg(coalesce(u.full_name, 'Admin') ORDER BY u.full_name), '[]'::jsonb)
        FROM lms.session_teachers st JOIN lms.users u ON u.id = st.admin_id WHERE st.session_id = s.id))
      ORDER BY p.completed_at DESC NULLS LAST)
    FROM lms.learner_progress p
    JOIN lms.modules m ON m.id = p.module_id AND m.parent_id IS NOT NULL
    LEFT JOIN lms.curriculum_sessions s ON s.id = p.source_session_id
    WHERE p.learner_id = auth.uid() AND p.status = 'completed'), '[]'::jsonb) END;
$$;
REVOKE ALL ON FUNCTION lms.get_my_completions() FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION lms.get_my_completions() TO authenticated;

COMMIT;
